import heapq


def min_meeting_rooms(intervals):
    ends = []                                        # a min-heap: when each room's current meeting ends
    for start, end in sorted(intervals):
        if ends and ends[0] <= start:                # the room that frees up first is already free
            heapq.heapreplace(ends, end)             # reuse it: its new meeting ends at `end`
        else:
            heapq.heappush(ends, end)                # every room is busy: open a new one
    return len(ends)
